                                                                                                <button type="button" onClick={() => updateSceneBlueprint(selectedSequence, selectedScene, { plot_commitments: currentScene.plot_commitments.filter((_, i) => i !== pci) })} className="text-ink-400 hover:text-blush-600 p-1 cursor-pointer" title="Remove Commitment"><Trash2 size={13} /></button>
